#include <stdio.h>
#include <stdlib.h>
typedef int element;
typedef struct StackNode {
    element item;
    struct StackNode *link;
} StackNode;
typedef struct {
    StackNode *top;
} LinkedStackType;
int is_empty(LinkedStackType *s)
{
    return (s->top == NULL);
}
// 삭제 함수
element pop(LinkedStackType *s)
{
    if( is_empty(s) ) {
        fprintf(stderr, "스택이 비어있음\n");
        exit(1);
    }
    else{
        StackNode *temp=s->top;
        int item = temp->item;
        s->top = s->top->link;
        free(temp);
        return item;
    }
}
int main(void)
{
    LinkedStackType s = { NULL };
    /* 앞선 push로 노드 3개가 쌓여 있다고 가정 */
    int x = pop(&s);
    return 0;
}

